/* ---------- Application Number Generator ---------- */
function getNextApplicationNumber(term) {
  const year = 2027;
  const storageKey = "CHJS_" + year + "_TERM_" + term;
  let serial = parseInt(localStorage.getItem(storageKey) || "0", 10);
  serial++;
  localStorage.setItem(storageKey, serial);
  return "CHJS-" + year + "-" + term + "-" + String(serial).padStart(4, "0");
}

/* ---------- Admission Form Submission ---------- */
const admissionForm = document.getElementById("admissionForm");
const submitMessage = document.getElementById("submitMessage");
const applicationNumber = document.getElementById("applicationNumber");
const applicationNumberField = document.getElementById("applicationNumberField");

if (admissionForm) {
  admissionForm.addEventListener("submit", async function (event) {
    event.preventDefault();

    const submitButton = admissionForm.querySelector(".application-submit");
    const termSelect = document.getElementById("term");
    const term = termSelect ? termSelect.value : "1";

    // Confirm first (before disabling button)
    const confirmed = confirm(
      "Are you sure all the information is correct and you want to submit this application?"
    );
    if (!confirmed) return;

    // Generate & set application number
    const newApplicationNumber = getNextApplicationNumber(term);
    if (applicationNumberField) {
      applicationNumberField.value = newApplicationNumber;
    }

    // Show submitting state
    if (submitButton) {
      submitButton.disabled = true;
      submitButton.innerHTML =
        '<i class="fa-solid fa-spinner fa-spin"></i> Submitting...';
    }

    try {
      // Only send real admission fields to the school email
      // (never send assessment questions or other UI fields)
      const allowedFields = [
        "_subject",
        "_template",
        "School",
        "Application Number",
        "Parent First Name",
        "Parent Last Name",
        "Phone Number",
        "Email Address",
        "Location / Residence",
        "Pupil First Name",
        "Pupil Last Name",
        "Date of Birth",
        "Gender",
        "Term of Joining",
        "Previous School",
        "Report Card",
        "Class Applying For"
      ];

      const formData = new FormData();
      const raw = new FormData(admissionForm);
      raw.forEach(function (value, key) {
        // Skip assessment answers (question0, question1, ...)
        if (/^question\d+$/i.test(key)) return;
        if (allowedFields.indexOf(key) === -1) return;
        // Skip empty optional file
        if (key === "Report Card" && (!value || (value instanceof File && !value.name))) return;
        formData.append(key, value);
      });

      const response = await fetch(admissionForm.action, {
        method: "POST",
        body: formData,
        headers: { Accept: "application/json" }
      });

      if (!response.ok) throw new Error("Submission failed");

      // Success UI
      if (submitMessage) {
        submitMessage.style.display = "block";
        submitMessage.style.backgroundColor = "#198754";
        submitMessage.style.color = "#ffffff";
        submitMessage.innerHTML = "✓ Application submitted successfully!";
      }

      if (applicationNumber) {
        applicationNumber.style.display = "block";
        applicationNumber.innerHTML =
          "Application Number: " + newApplicationNumber;
        localStorage.setItem("latestApplicationNumber", newApplicationNumber);
      }

      // Save data for PDF
      localStorage.setItem(
        "admissionData",
        JSON.stringify({
          childFirst: document.getElementById("childFirst")?.value || "",
          childLast: document.getElementById("childLast")?.value || "",
          dob: document.getElementById("dob")?.value || "",
          gender: document.getElementById("gender")?.value || "",
          class: document.getElementById("class")?.value || "",
          term: document.getElementById("term")?.value || "",
          parentFirst: document.getElementById("parentFirst")?.value || "",
          parentLast: document.getElementById("parentLast")?.value || "",
          phone: document.getElementById("phone")?.value || "",
          location: document.getElementById("residencelocation")?.value || ""
        })
      );

      // Show download area
      const admissionDoc = document.getElementById("admission-document");
      if (admissionDoc) admissionDoc.style.display = "block";

      // Clear assessment results after successful submission
      if (typeof clearAssessmentResults === "function") {
        clearAssessmentResults();
      }

      // Restore button & reset form
      if (submitButton) {
        submitButton.disabled = false;
        submitButton.innerHTML =
          '<i class="fa-solid fa-paper-plane"></i> Submit Application';
      }
      admissionForm.reset();

      // Hide final submit area again
      const finalSubmitArea = document.getElementById("finalSubmitArea");
      if (finalSubmitArea) finalSubmitArea.style.display = "none";

      // Hide messages after delay
      setTimeout(function () {
        if (submitMessage) submitMessage.style.display = "none";
      }, 5000);
      setTimeout(function () {
        if (applicationNumber) applicationNumber.style.display = "none";
      }, 15000);
    } catch (error) {
      console.error("Admission submission error:", error);
      if (submitMessage) {
        submitMessage.style.display = "block";
        submitMessage.style.backgroundColor = "#dc3545";
        submitMessage.style.color = "#ffffff";
        submitMessage.innerHTML = "✕ Submission failed. Please try again.";
      }
      if (submitButton) {
        submitButton.disabled = false;
        submitButton.innerHTML =
          '<i class="fa-solid fa-paper-plane"></i> Submit Application';
      }
    }
  });
}

/* ---------- Embedded school logo (always available for PDF) ---------- */
const SCHOOL_LOGO_BASE64 = "data:image/png;base64,";

const STAMP_BASE64 = "data:image/png;base64,";

/* ---------- PDF Generator (logo + real signatures) ---------- */
function generateAdmissionPDF() {
  if (!window.jspdf) {
    alert("PDF library not loaded. Please refresh the page and try again.");
    return;
  }

  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF("p", "mm", "a4");
  const pageWidth = pdf.internal.pageSize.getWidth();

  let admissionData = {};
  try {
    admissionData = JSON.parse(localStorage.getItem("admissionData")) || {};
  } catch (e) {
    admissionData = {};
  }

  const appNo =
    localStorage.getItem("latestApplicationNumber") || "CHJS-2027-1-0001";

  // Draw the full PDF once images are ready (or timed out)
  function drawPDF(logoImg, sigLazarus, sigMoses, stampImg) {
    // Light logo watermark in the background (centered, large, faded)
    if (logoImg) {
      try {
        const wmSize = 110;
        const wmX = (pageWidth - wmSize) / 2;
        const wmY = 95;
        if (pdf.GState && pdf.saveGraphicsState) {
          pdf.saveGraphicsState();
          pdf.setGState(new pdf.GState({ opacity: 0.07 }));
          pdf.addImage(logoImg, "PNG", wmX, wmY, wmSize, wmSize);
          pdf.restoreGraphicsState();
        } else {
          // Fallback: still place logo faintly by drawing smaller
          pdf.addImage(logoImg, "PNG", wmX + 25, wmY + 25, 60, 60);
        }
      } catch (e) {
        console.warn("Watermark skipped:", e);
      }
    }

    /// ===== Beautiful page border – extreme edges (covers everything) =====
    const pageH = pdf.internal.pageSize.getHeight();
    const margin = 2.5;                  // almost at the very edge of the paper
    // Outer blue border
    pdf.setDrawColor(8, 59, 140);
    pdf.setLineWidth(1.5);
    pdf.rect(margin, margin, pageWidth - margin * 2, pageH - margin * 2);
    // Inner thinner blue border
    pdf.setLineWidth(0.5);
    pdf.rect(margin + 2, margin + 2, pageWidth - (margin + 2) * 2, pageH - (margin + 2) * 2);
    // Gold accent corners
    pdf.setDrawColor(180, 120, 20);
    pdf.setLineWidth(1.1);
    const c = 9; // corner length
    // top-left
    pdf.line(margin, margin + c, margin, margin);
    pdf.line(margin, margin, margin + c, margin);
    // top-right
    pdf.line(pageWidth - margin - c, margin, pageWidth - margin, margin);
    pdf.line(pageWidth - margin, margin, pageWidth - margin, margin + c);
    // bottom-left
    pdf.line(margin, pageH - margin - c, margin, pageH - margin);
    pdf.line(margin, pageH - margin, margin + c, pageH - margin);
    // bottom-right
    pdf.line(pageWidth - margin - c, pageH - margin, pageWidth - margin, pageH - margin);
    pdf.line(pageWidth - margin, pageH - margin, pageWidth - margin, pageH - margin - c);
    // Reset
    pdf.setLineWidth(0.2);

    // Header line under logo area
    pdf.setDrawColor(8, 59, 140);
    pdf.line(15, 40, pageWidth - 15, 40);

    // Logo – top left, clearly next to school name
    if (logoImg) {
      try {
        pdf.addImage(logoImg, "PNG", 14, 6, 30, 30);
      } catch (e) {
        console.warn("Could not add logo:", e);
      }
    }

    // School name next to logo
    pdf.setTextColor(8, 59, 140);
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(18);
    pdf.text("CHILDREN'S HOPE", 48, 16);
    pdf.setFontSize(11);
    pdf.text("JUNIOR SCHOOL - NAMUKOOGE", 48, 24);
    pdf.setFont("helvetica", "italic");
    pdf.setFontSize(9);
    pdf.setTextColor(180, 120, 20); // gold motto colour
    pdf.text("In God We Trust", 48, 32);

    // Contacts (right)
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(8);
    pdf.setTextColor(50, 50, 50);
    pdf.text("Tel: +256 702 879655", pageWidth - 15, 16, { align: "right" });
    pdf.text("Tel: +256 761 118413", pageWidth - 15, 22, { align: "right" });
    pdf.text("Namukooge, Kaliro District, Uganda", pageWidth - 15, 28, {
      align: "right"
    });
    pdf.text(
      "Email: childrenshopejuniorschool@gmail.com",
      pageWidth - 15,
      34,
      { align: "right" }
    );

    // Title
    pdf.setTextColor(8, 59, 140);
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(18);
    pdf.text("ADMISSION FORM", pageWidth / 2, 58, { align: "center" });

    // Application details
    pdf.setFontSize(11);
    pdf.setTextColor(40, 40, 40);
    pdf.text("Application Number:", 25, 75);
    pdf.setFont("helvetica", "bold");
    pdf.text(appNo, 75, 75);
    pdf.setFont("helvetica", "normal");
    pdf.text("Admission Date:", 25, 85);
    const today = new Date();
    const dd = String(today.getDate()).padStart(2, "0");
    const mm = String(today.getMonth() + 1).padStart(2, "0");
    const yyyy = today.getFullYear();
    const formattedDate = dd + "/" + mm + "/" + yyyy; // e.g. 22/09/2026 fits on stamp
    pdf.text(formattedDate, 75, 85);

    // Student Information
    pdf.setFont("helvetica", "bold");
    pdf.setTextColor(8, 59, 140);
    pdf.text("PUPIL INFORMATION", 25, 103);
    pdf.setFont("helvetica", "normal");
    pdf.setTextColor(40, 40, 40);
    pdf.text("Pupil Name:", 25, 115);
    pdf.text(
      (admissionData.childFirst || "") + " " + (admissionData.childLast || ""),
      75,
      115
    );
    pdf.text("Date of Birth:", 25, 127);
    pdf.text(admissionData.dob || "", 75, 127);
    pdf.text("Gender:", 25, 139);
    pdf.text(admissionData.gender || "", 75, 139);
    pdf.text("Admitted Class:", 25, 151);
    pdf.text(admissionData.class || "", 75, 151);
    pdf.text("Joining Term:", 25, 163);
    pdf.text("Term " + (admissionData.term || ""), 75, 163);

    // Parent Information
    pdf.setFont("helvetica", "bold");
    pdf.setTextColor(8, 59, 140);
    pdf.text("PARENT / GUARDIAN INFORMATION", 25, 183);
    pdf.setFont("helvetica", "normal");
    pdf.setTextColor(40, 40, 40);
    pdf.text("Parent / Guardian:", 25, 195);
    pdf.text(
      (admissionData.parentFirst || "") +
        " " +
        (admissionData.parentLast || ""),
      75,
      195
    );
    pdf.text("Phone:", 25, 207);
    pdf.text(admissionData.phone || "", 75, 207);
    pdf.text("Location:", 25, 219);
    pdf.text(admissionData.location || "", 75, 219);

    // School Administration
    pdf.setFont("helvetica", "bold");
    pdf.setTextColor(8, 59, 140);
    pdf.setFontSize(12);
    pdf.text("SCHOOL ADMINISTRATION", pageWidth / 2, 235, { align: "center" });

    // ----- Left director -----
    pdf.setFont("helvetica", "normal");
    pdf.setTextColor(40, 40, 40);
    pdf.setFontSize(10);
    pdf.text("Mr. Lazarus Semujju", 40, 250, { align: "center" });
    pdf.setFontSize(8);
    pdf.text("Director", 40, 256, { align: "center" });
    if (sigLazarus) {
      try { pdf.addImage(sigLazarus, "PNG", 22, 260, 36, 12); } catch (e) {}
    } else {
      pdf.setFont("helvetica", "italic");
      pdf.setFontSize(9);
      pdf.setTextColor(20, 20, 120);
      pdf.text("Lazarus Semujju", 40, 268, { align: "center" });
    }
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(8);
    pdf.setTextColor(80, 80, 80);
    pdf.text("Signature", 40, 276, { align: "center" });

    // ----- Right director -----
    pdf.setFont("helvetica", "normal");
    pdf.setTextColor(40, 40, 40);
    pdf.setFontSize(10);
    pdf.text("Mr. Moses Kusemererwa", 170, 250, { align: "center" });
    pdf.setFontSize(8);
    pdf.text("Director", 170, 256, { align: "center" });
    if (sigMoses) {
      try { pdf.addImage(sigMoses, "PNG", 152, 260, 36, 12); } catch (e) {}
    } else {
      pdf.setFont("helvetica", "italic");
      pdf.setFontSize(9);
      pdf.setTextColor(20, 20, 120);
      pdf.text("Moses Kusemererwa", 170, 268, { align: "center" });
    }
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(8);
    pdf.setTextColor(80, 80, 80);
    pdf.text("Signature", 170, 276, { align: "center" });

    // ----- STAMP between the two signatures (embedded, always loads) -----
    const stampW = 28;
    const stampH = 28;
    const stampX = (pageWidth - stampW) / 2;
    const stampY = 248;
    if (stampImg) {
      try {
        pdf.addImage(stampImg, "PNG", stampX, stampY, stampW, stampH);
      } catch (e) {
        console.warn("stamp draw failed", e);
      }
    }
    // Red date DD/MM/YYYY on the Date: line inside the stamp
    pdf.setTextColor(200, 0, 0);
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(4.5);
    pdf.text(formattedDate, stampX + stampW * 0.55, stampY + stampH * 0.78, {
      align: "center"
    });

    // Thank-you message – one single line, extended left & right
    pdf.setFont("helvetica", "italic");
    pdf.setFontSize(7.2);                 // slightly smaller so it fits on one line
    pdf.setTextColor(8, 59, 140);
    const thankMsg =
      "Thank you for choosing Children's Hope Junior School. We look forward to welcoming your child and walking with your family in faith, learning, and hope.";
    pdf.text(thankMsg, pageWidth / 2, 290, { align: "center" });
    // File name
    const first = (admissionData.childFirst || "").trim();
    const last = (admissionData.childLast || "").trim();
    let fullName = (first + " " + last).trim() || "Pupil";
    fullName = fullName.replace(/[\\/:*?"<>|]/g, "").replace(/\s+/g, " ");
    const fileName = fullName + "AdmitChildren'sHopeJuniorSchool.pdf";
    pdf.save(fileName);
  }

  // Load embedded logo + signatures + official stamp
  const logo = new Image();
  const sigL = new Image();
  const sigM = new Image();
  const stamp = new Image();
  sigL.crossOrigin = "anonymous";
  sigM.crossOrigin = "anonymous";
  stamp.crossOrigin = "anonymous";

  let loaded = { logo: false, sigL: false, sigM: false, stamp: false };
  let finished = false;

  function tryFinish() {
    if (finished) return;
    if (loaded.logo && loaded.sigL && loaded.sigM && loaded.stamp) {
      finished = true;
      drawPDF(
        logo.complete && logo.naturalWidth ? logo : null,
        sigL.complete && sigL.naturalWidth ? sigL : null,
        sigM.complete && sigM.naturalWidth ? sigM : null,
        stamp.complete && stamp.naturalWidth ? stamp : null
      );
    }
  }

  function mark(key) {
    loaded[key] = true;
    tryFinish();
  }

  logo.onload = function () { mark("logo"); };
  logo.onerror = function () { mark("logo"); };
  sigL.onload = function () { mark("sigL"); };
  sigL.onerror = function () { mark("sigL"); };
  sigM.onload = function () { mark("sigM"); };
  sigM.onerror = function () { mark("sigM"); };
  stamp.onload = function () { mark("stamp"); };
  stamp.onerror = function () { mark("stamp"); };

  setTimeout(function () {
    if (!finished) {
      finished = true;
      drawPDF(
        logo.complete && logo.naturalWidth ? logo : null,
        sigL.complete && sigL.naturalWidth ? sigL : null,
        sigM.complete && sigM.naturalWidth ? sigM : null,
        stamp.complete && stamp.naturalWidth ? stamp : null
      );
    }
  }, 3500);

  logo.src = SCHOOL_LOGO_BASE64;
  sigL.src = "images/ls.png";
  sigM.src = "images/mk.png";
  stamp.src = STAMP_BASE64;
}

/* ---------- Class-dependent fields (Previous School / Report Card) ---------- */
document.addEventListener("DOMContentLoaded", function () {
  const classSelect = document.getElementById("class");
  const previousSchoolArea = document.querySelector(".previous-school-area");
  const previousSchool = document.getElementById("previousSchool");
  const reportCardArea = document.querySelector(".report-card-area");

  if (classSelect) {
    classSelect.addEventListener("change", function () {
      if (previousSchoolArea && previousSchool) {
        if (this.value === "Baby Class") {
          previousSchoolArea.style.display = "none";
          previousSchool.removeAttribute("required");
          previousSchool.value = "";
        } else {
          previousSchoolArea.style.display = "block";
          previousSchool.setAttribute("required", "required");
        }
      }
      if (reportCardArea) {
        reportCardArea.style.display =
          this.value === "Baby Class" ? "none" : "block";
      }
    });
  }
});

