/* ---------- Gallery Lightbox ---------- */
document.addEventListener("DOMContentLoaded", function () {
  const lightbox = document.getElementById("imageLightbox");
  const lightboxImage = document.getElementById("lightboxImage");
  const closeLightbox = document.getElementById("closeLightbox");

  if (!lightbox || !lightboxImage || !closeLightbox) return;

  document.querySelectorAll(".gallery-item img").forEach(function (image) {
    image.addEventListener("click", function () {
      lightboxImage.src = this.src;
      lightbox.style.display = "flex";
    });
  });

  closeLightbox.addEventListener("click", function () {
    lightbox.style.display = "none";
  });

  lightbox.addEventListener("click", function (event) {
    if (event.target === lightbox) lightbox.style.display = "none";
  });
});

/* =========================================
   ADMISSION ASSESSMENT
========================================= */
let selectedQuestions = [];
let recommendedClass = "";

function shuffleArray(array) {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

function clearAssessmentFeedback() {
  const status = document.getElementById("assessmentStatus");
  const result = document.getElementById("assessmentResult");
  const decision = document.getElementById("decisionBox");
  const warning = document.getElementById("assessmentWarning");
  if (status) {
    status.style.display = "none";
    status.textContent = "";
  }
  if (result) {
    result.style.display = "none";
    result.innerHTML = "";
  }
  if (decision) {
    decision.style.display = "none";
    decision.innerHTML = "";
  }
  if (warning) {
    warning.style.display = "none";
    warning.textContent = "";
  }
}

function getRecommendedClass(selectedClass, percentage) {
  const classes = [
    "Baby Class",
    "Middle Class",
    "Top Class",
    "Primary One",
    "Primary Two",
    "Primary Three",
    "Primary Four",
    "Primary Five",
    "Primary Six",
    "Primary Seven"
  ];
  const currentIndex = classes.indexOf(selectedClass);
  if (currentIndex === -1) return selectedClass;
  if (percentage >= 40) return selectedClass;
  let recommendedIndex = currentIndex - 1;
  if (recommendedIndex < 0) recommendedIndex = 0;
  return classes[recommendedIndex];
}

function createFallingEffect(type) {
  const flowers = ["🌸", "🌺", "🌼", "🌷", "💮"];
  const leaves = ["🍃", "🍂", "🌿"];
  const items = type === "pass" ? flowers : leaves;
  const amount = type === "pass" ? 35 : 18;

  for (let i = 0; i < amount; i++) {
    const el = document.createElement("span");
    el.classList.add("falling-effect");
    el.classList.add(type === "pass" ? "falling-flower" : "falling-leaf");
    el.textContent = items[Math.floor(Math.random() * items.length)];
    el.style.left = Math.random() * 100 + "vw";
    el.style.animationDuration = 5 + Math.random() * 5 + "s";
    el.style.animationDelay = Math.random() * 2 + "s";
    el.style.fontSize = 22 + Math.random() * 18 + "px";
    document.body.appendChild(el);
    setTimeout(function () {
      el.remove();
    }, 12000);
  }
}

function clearAssessmentResults() {
  const status = document.getElementById("assessmentStatus");
  const result = document.getElementById("assessmentResult");
  const decision = document.getElementById("decisionBox");
  const warning = document.getElementById("assessmentWarning");
  const notice = document.getElementById("assessmentNotice");
  const container = document.getElementById("assessmentContainer");

  if (status) {
    status.style.display = "none";
    status.textContent = "";
  }
  if (result) {
    result.style.display = "none";
    result.innerHTML = "";
  }
  if (decision) {
    decision.style.display = "none";
    decision.innerHTML = "";
  }
  if (warning) {
    warning.style.display = "none";
    warning.textContent = "";
  }
  if (notice) notice.style.display = "none";
  if (container) container.style.display = "none";
}

function acceptPlacement(event) {
  if (event) event.preventDefault();

  // Demote: set the class field to the recommended lower class
  const classField = document.getElementById("class");
  if (classField && recommendedClass) {
    classField.value = recommendedClass;
  }

  // Hide all assessment results
  clearAssessmentResults();

  // Show the final submit button
  const finalSubmitArea = document.getElementById("finalSubmitArea");
  if (finalSubmitArea) finalSubmitArea.style.display = "block";

  if (classField) {
    classField.scrollIntoView({ behavior: "smooth", block: "center" });
  }
}

