document.addEventListener("DOMContentLoaded", function () {
  const classSelect = document.getElementById("class");
  const assessmentNotice = document.getElementById("assessmentNotice");
  const assessmentContainer = document.getElementById("assessmentContainer");
  const questionsContainer = document.getElementById("assessmentQuestions");

  if (!classSelect || !assessmentContainer || !questionsContainer) return;

  classSelect.addEventListener("change", function () {
    clearAssessmentFeedback();
    const selectedClass = this.value;
    const assessmentClasses = [
      "Primary One",
      "Primary Two",
      "Primary Three",
      "Primary Four",
      "Primary Five",
      "Primary Six",
      "Primary Seven"
    ];

    // Hide assessment for nursery classes
    if (!assessmentClasses.includes(selectedClass)) {
      if (assessmentNotice) assessmentNotice.style.display = "none";
      assessmentContainer.style.display = "none";
      questionsContainer.innerHTML = "";
      const finalSubmit = document.getElementById("finalSubmitArea");
      if (finalSubmit) finalSubmit.style.display = "block";
      return;
    }

    // Show assessment
    if (assessmentNotice) assessmentNotice.style.display = "block";
    assessmentContainer.style.display = "block";
    questionsContainer.style.display = "block";
    const submitArea = document.querySelector(".assessment-submit-area");
    if (submitArea) submitArea.style.display = "flex";

    // Hide main submit until assessment is done
    const finalSubmit = document.getElementById("finalSubmitArea");
    if (finalSubmit) finalSubmit.style.display = "none";

    const questions = QUESTION_BANKS[selectedClass] || [];
    selectedQuestions = shuffleArray(questions).slice(0, 20);
    questionsContainer.innerHTML = "";

    selectedQuestions.forEach(function (item, index) {
      const questionDiv = document.createElement("div");
      questionDiv.className = "assessment-question";

      const title = document.createElement("p");
      const strong = document.createElement("strong");
      strong.textContent = index + 1 + ". " + item.question;
      title.appendChild(strong);
      questionDiv.appendChild(title);

      const shuffledOptions = [...item.options].sort(function () {
        return Math.random() - 0.5;
      });

      const optionsDiv = document.createElement("div");
      optionsDiv.className = "assessment-options";

      shuffledOptions.forEach(function (option) {
        const label = document.createElement("label");
        const radio = document.createElement("input");
        radio.type = "radio";
        radio.name = "question" + index;
        radio.value = option;
        label.appendChild(radio);
        label.appendChild(document.createTextNode(" " + option));
        optionsDiv.appendChild(label);
      });

      questionDiv.appendChild(optionsDiv);
      questionsContainer.appendChild(questionDiv);
    });

    // Unanswered tracker
    const unansweredBox = document.getElementById("unansweredQuestions");
    function updateUnanswered() {
      if (!unansweredBox) return;
      const unanswered = [];
      document.querySelectorAll(".assessment-question").forEach(function (q, i) {
        if (!q.querySelector("input[type='radio']:checked")) {
          unanswered.push(i + 1);
        }
      });
      if (unanswered.length === 0) {
        unansweredBox.textContent = "✓ All questions answered";
        const warning = document.getElementById("assessmentWarning");
        if (warning) warning.style.display = "none";
      } else {
        unansweredBox.textContent = "Unanswered: Q" + unanswered.join(", Q");
      }
    }
    updateUnanswered();
    document
      .querySelectorAll(".assessment-question input[type='radio']")
      .forEach(function (input) {
        input.addEventListener("change", updateUnanswered);
      });
  });

  // Submit Assessment
  const submitAssessment = document.getElementById("submitAssessment");
  if (submitAssessment) {
    submitAssessment.addEventListener("click", function (event) {
      event.preventDefault();

      const allQuestions = document.querySelectorAll(".assessment-question");
      let unanswered = 0;
      allQuestions.forEach(function (q) {
        if (!q.querySelector("input[type='radio']:checked")) unanswered++;
      });

      if (unanswered > 0) {
        const warning = document.getElementById("assessmentWarning");
        if (warning) {
          warning.style.display = "block";
          warning.textContent =
            "Please answer all assessment questions before submitting.";
        }
        return;
      }

      let score = 0;
      selectedQuestions.forEach(function (item, index) {
        const chosen = document.querySelector(
          "input[name='question" + index + "']:checked"
        );
        if (chosen && chosen.value === item.answer) score++;
      });

      const percentage = Math.round(
        (score / selectedQuestions.length) * 100
      );
      const selectedClass = document.getElementById("class").value;
      recommendedClass = getRecommendedClass(selectedClass, percentage);

      // Hide notice
      const notice = document.getElementById("assessmentNotice");
      if (notice) notice.style.display = "none";

      // Marking animation
      const status = document.getElementById("assessmentStatus");
      if (status) {
        status.style.display = "block";
        status.textContent = "Assessment completed successfully. Marking...";
        status.scrollIntoView({ behavior: "smooth", block: "center" });
      }

      setTimeout(function () {
        if (status) status.textContent = "Grading completed. Preparing your result...";

        setTimeout(function () {
          if (status) {
            status.style.display = "none";
            status.textContent = "";
          }

          const result = document.getElementById("assessmentResult");
          if (result) {
            result.style.display = "block";
            if (percentage >= 40) {
              createFallingEffect("pass");
              result.innerHTML =
                "<h3>Assessment Result</h3>" +
                "<p>Score: " +
                score +
                " / " +
                selectedQuestions.length +
                "</p>" +
                "<p>Percentage: " +
                percentage +
                "%</p>" +
                "<p>✓ Congratulations, you may proceed with admission.</p>";
              const finalSubmit = document.getElementById("finalSubmitArea");
              if (finalSubmit) finalSubmit.style.display = "block";
            } else {
              createFallingEffect("fail");
              result.innerHTML =
                "<h3>Assessment Result</h3>" +
                "<p>Score: " +
                score +
                " / " +
                selectedQuestions.length +
                "</p>" +
                "<p>Percentage: " +
                percentage +
                "%</p>" +
                "<p>The assessment suggests that the child may join " +
                recommendedClass +
                ".</p>";

              const decisionBox = document.getElementById("decisionBox");
              if (decisionBox) {
                decisionBox.style.display = "block";
                decisionBox.innerHTML =
                  "<p>Would you like to proceed?</p>" +
                  "<button type='button' class='yes-btn' onclick='acceptPlacement(event)'>YES</button>" +
                  "<button type='button' class='director-btn' onclick='contactDirectors(event)'>DISCUSS WITH DIRECTORS</button>" +
                  "<button type='button' class='no-btn' onclick='declinePlacement(event)'>NO</button>";
              }
            }
          }
        }, 2000);
      }, 3000);
    });
  }
});
